#include <IRremote.hpp>
#include <LedControl.h>

LedControl lc = LedControl(12, 11, 10, 1); // DIN, CLK, CS
const int IR_PIN = 2;

const byte happyFace[8] = {
  B00111100, B01000010, B10100101, B10000001,
  B10100101, B10011001, B01000010, B00111100
};

void setup() {
  IrReceiver.begin(IR_PIN);
  lc.shutdown(0, false);
  lc.setIntensity(0, 8);
  lc.clearDisplay(0);
}

void loop() {
  if (IrReceiver.decode()) {
    unsigned long cmd = IrReceiver.decodedIRData.command;
    // Switch expression based on remote key command
    IrReceiver.resume();
  }
}
